     6→/**
     7→ * Upgrade a state from Electra to Fulu.
     8→ */
     9→export function upgradeStateToFulu(stateElectra: CachedBeaconStateElectra): CachedBeaconStateFulu {
    10→  const {config} = stateElectra;
    11→
    12→  const stateElectraNode = ssz.electra.BeaconState.commitViewDU(stateElectra);
    13→  const stateFuluView = ssz.fulu.BeaconState.getViewDU(stateElectraNode);
    14→
    15→  const stateFulu = getCachedBeaconState(stateFuluView, stateElectra);
    16→
    17→  stateFulu.fork = ssz.phase0.Fork.toViewDU({
    18→    previousVersion: stateElectra.fork.currentVersion,
    19→    currentVersion: config.FULU_FORK_VERSION,
    20→    epoch: stateElectra.epochCtx.epoch,
    21→  });
    22→
    23→  stateFulu.proposerLookahead = ssz.fulu.ProposerLookahead.toViewDU(initializeProposerLookahead(stateElectra));
    24→
    25→  stateFulu.commit();
    26→  // Clear cache to ensure the cache of electra fields is not used by new fulu fields
    27→  // biome-ignore lint/complexity/useLiteralKeys: It is a protected attribute
    28→  stateFulu["clearCache"]();
    29→
    30→  return stateFulu;
    31→}
