     1→import {ForkSeq, MIN_SEED_LOOKAHEAD, SLOTS_PER_EPOCH} from "@lodestar/params";
     2→import {ssz} from "@lodestar/types";
     3→import {CachedBeaconStateFulu, EpochTransitionCache} from "../types.js";
     4→import {computeEpochShuffling} from "../util/epochShuffling.js";
     5→import {computeProposerIndices} from "../util/seed.js";
     6→
     7→/**
     8→ * This function updates the `proposer_lookahead` field in the beacon state
     9→ * by shifting out proposer indices from the earliest epoch and appending new
    10→ * proposer indices for the latest epoch. With `MIN_SEED_LOOKAHEAD` set to `1`,
    11→ * this means that at the start of epoch `N`, the proposer lookahead for epoch
    12→ * `N+1` will be computed and included in the beacon state's lookahead.
    13→ */
    14→export function processProposerLookahead(
    15→  fork: ForkSeq,
    16→  state: CachedBeaconStateFulu,
    17→  cache: EpochTransitionCache
    18→): void {
    19→  // Shift out proposers in the first epoch
    20→  const remainingProposerLookahead = state.proposerLookahead.getAll().slice(SLOTS_PER_EPOCH);
    21→
    22→  // Fill in the last epoch with new proposer indices
    23→  const epoch = state.epochCtx.epoch + MIN_SEED_LOOKAHEAD + 1;
    24→
    25→  const shuffling =
    26→    state.epochCtx.shufflingCache?.getSync(epoch, cache.nextShufflingDecisionRoot, {
    27→      state,
    28→      activeIndices: cache.nextShufflingActiveIndices,
    29→    }) ??
    30→    // Only for testing. shufflingCache should always be available in prod
    31→    computeEpochShuffling(state, cache.nextShufflingActiveIndices, epoch);
    32→
    33→  const lastEpochProposerLookahead = computeProposerIndices(fork, state, shuffling, epoch);
    34→
    35→  state.proposerLookahead = ssz.fulu.ProposerLookahead.toViewDU([
    36→    ...remainingProposerLookahead,
    37→    ...lastEpochProposerLookahead,
    38→  ]);
    39→}
