     2→import {BeaconConfig} from "@lodestar/config";
     3→import {ForkSeq} from "@lodestar/params";
     4→import {computeStartSlotAtEpoch} from "@lodestar/state-transition";
     5→import {Epoch, fulu, phase0, ssz} from "@lodestar/types";
