     9→import {getCurrentAndNextForkBoundary} from "./forks.js";
    10→import {NetworkConfig} from "./networkConfig.js";
    11→
    12→export enum ENRKey {
    13→  tcp = "tcp",
    14→  eth2 = "eth2",
    15→  attnets = "attnets",
    16→  syncnets = "syncnets",
    17→  cgc = "cgc",
    18→  nfd = "nfd",
    19→}
    20→export enum SubnetType {
    21→  attnets = "attnets",
    22→  syncnets = "syncnets",
    23→}
    24→
    25→export type MetadataOpts = {
    26→  metadata?: fulu.Metadata;
    27→};
    28→
    29→export type MetadataModules = {
    30→  networkConfig: NetworkConfig;
    31→  logger: Logger;
    32→  onSetValue: (key: string, value: Uint8Array) => void;
    33→};
    34→
    35→/**
    36→ * Implementation of Ethereum Consensus p2p MetaData.
    37→ * For the spec that this code is based on, see:
    38→ * https://github.com/ethereum/consensus-specs/blob/v1.1.10/specs/phase0/p2p-interface.md#metadata
    39→ */
    40→export class MetadataController {
    41→  private onSetValue: (key: string, value: Uint8Array) => void;
    42→  private networkConfig: NetworkConfig;
    43→  private logger: Logger;
    44→  private _metadata: fulu.Metadata;
    45→
    46→  constructor(opts: MetadataOpts, modules: MetadataModules) {
    47→    this.networkConfig = modules.networkConfig;
    48→    this.logger = modules.logger;
    49→    this.onSetValue = modules.onSetValue;
    50→    this._metadata = opts.metadata ?? {
    51→      ...ssz.fulu.Metadata.defaultValue(),
    52→      custodyGroupCount: modules.networkConfig.custodyConfig.targetCustodyGroupCount,
    53→    };
    54→  }
    55→
    56→  upstreamValues(currentEpoch: Epoch): void {
    57→    // updateEth2Field() MUST be called with clock epoch
    58→    this.updateEth2Field(currentEpoch);
    59→
    60→    this.onSetValue(ENRKey.attnets, ssz.phase0.AttestationSubnets.serialize(this._metadata.attnets));
    61→
    62→    const config = this.networkConfig.config;
    63→
    64→    if (config.getForkSeq(computeStartSlotAtEpoch(currentEpoch)) >= ForkSeq.altair) {
    65→      // Only persist syncnets if altair fork is already activated. If currentFork is altair but head is phase0
    66→      // adding syncnets to the ENR is not a problem, we will just have a useless field for a few hours.
    67→      this.onSetValue(ENRKey.syncnets, ssz.phase0.AttestationSubnets.serialize(this._metadata.syncnets));
    68→    }
    69→
    70→    // Set CGC regardless of fork. It may be useful to clients before Fulu, and will be ignored otherwise.
    71→    this.onSetValue(ENRKey.cgc, serializeCgc(this._metadata.custodyGroupCount));
    72→  }
    73→
    74→  get seqNumber(): bigint {
    75→    return this._metadata.seqNumber;
    76→  }
    77→
    78→  get syncnets(): BitArray {
    79→    return this._metadata.syncnets;
    80→  }
    81→
    82→  set syncnets(syncnets: BitArray) {
    83→    this.onSetValue(ENRKey.syncnets, ssz.altair.SyncSubnets.serialize(syncnets));
    84→    this._metadata.syncnets = syncnets;
    85→  }
    86→
    87→  get attnets(): BitArray {
    88→    return this._metadata.attnets;
    89→  }
    90→
    91→  set attnets(attnets: BitArray) {
    92→    this.onSetValue(ENRKey.attnets, ssz.phase0.AttestationSubnets.serialize(attnets));
    93→    this._metadata.seqNumber++;
    94→    this._metadata.attnets = attnets;
    95→  }
    96→
    97→  get custodyGroupCount(): number {
    98→    return this._metadata.custodyGroupCount;
    99→  }
   100→
   101→  set custodyGroupCount(custodyGroupCount: number) {
   102→    if (custodyGroupCount === this._metadata.custodyGroupCount) {
   103→      return;
   104→    }
   105→    this.onSetValue(ENRKey.cgc, serializeCgc(custodyGroupCount));
   106→    this.logger.debug("Updated cgc field in ENR", {custodyGroupCount});
   107→    this._metadata.seqNumber++;
   108→    this._metadata.custodyGroupCount = custodyGroupCount;
   109→  }
   110→
   111→  /** Consumers that need the phase0.Metadata type can just ignore the .syncnets property */
   112→  get json(): fulu.Metadata {
   113→    return this._metadata;
   114→  }
   115→
   116→  /**
   117→   * From spec:
   118→   *   fork_digest is compute_fork_digest(current_fork_version, genesis_validators_root) where
   119→   *   - current_fork_version is the fork version at the node's current epoch defined by the wall-clock time (not
   120→   *     necessarily the epoch to which the node is sync)
   121→   *   - genesis_validators_root is the static Root found in state.genesis_validators_root
   122→   *   - epoch of fork boundary is used to get blob parameters of current Blob Parameter Only (BPO) fork
   123→   *
   124→   * 1. MUST be called on start to populate ENR
   125→   * 2. Network MUST call this method on fork transition.
   126→   *    Current Clock implementation ensures no race conditions, epoch is correct if re-fetched
   127→   */
   128→  updateEth2Field(epoch: Epoch): void {
   129→    const config = this.networkConfig.config;
   130→    const enrForkId = getENRForkID(config, epoch);
   131→    const {forkDigest, nextForkVersion, nextForkEpoch} = enrForkId;
   132→    this.onSetValue(ENRKey.eth2, ssz.phase0.ENRForkID.serialize(enrForkId));
   133→    this.logger.debug("Updated eth2 field in ENR", {
   134→      forkDigest: toHex(forkDigest),
   135→      nextForkVersion: toHex(nextForkVersion),
   136→      nextForkEpoch,
   137→    });
   138→
   139→    const nextForkDigest =
   140→      nextForkEpoch !== FAR_FUTURE_EPOCH
   141→        ? config.forkBoundary2ForkDigest(config.getForkBoundaryAtEpoch(nextForkEpoch))
   142→        : ssz.ForkDigest.defaultValue();
   143→    this.onSetValue(ENRKey.nfd, nextForkDigest);
   144→    this.logger.debug("Updated nfd field in ENR", {nextForkDigest: toHex(nextForkDigest)});
   145→  }
   146→}
   147→
   148→export function getENRForkID(config: BeaconConfig, clockEpoch: Epoch): phase0.ENRForkID {
   149→  const {currentBoundary, nextBoundary} = getCurrentAndNextForkBoundary(config, clockEpoch);
   150→
   151→  return {
   152→    // Current fork digest
   153→    forkDigest: config.forkBoundary2ForkDigest(currentBoundary),
   154→    // Next planned fork version
   155→    nextForkVersion: nextBoundary
   156→      ? config.forks[nextBoundary.fork].version
   157→      : config.forks[currentBoundary.fork].version,
   158→    // Next fork epoch
   159→    nextForkEpoch: nextBoundary ? nextBoundary.epoch : FAR_FUTURE_EPOCH,
   160→  };
   161→}
