    15→type IrrelevantPeerType =
    16→  | {code: IrrelevantPeerCode.INCOMPATIBLE_FORKS; ours: ForkDigest; theirs: ForkDigest}
    17→  | {code: IrrelevantPeerCode.DIFFERENT_CLOCKS; slotDiff: number}
    18→  | {code: IrrelevantPeerCode.NO_EARLIEST_AVAILABLE_SLOT}
    19→  | {code: IrrelevantPeerCode.DIFFERENT_FINALIZED; expectedRoot: Root; remoteRoot: Root};
    20→
    21→/**
    22→ * Process a `Status` message to determine if a peer is relevant to us. If the peer is
    23→ * irrelevant the reason is returned.
    24→ */
    25→export function assertPeerRelevance(
    26→  forkName: ForkName,
    27→  remote: Status,
    28→  local: Status,
    29→  currentSlot: Slot
    30→): IrrelevantPeerType | null {
    31→  // The node is on a different network/fork
    32→  if (!ssz.ForkDigest.equals(local.forkDigest, remote.forkDigest)) {
    33→    return {
    34→      code: IrrelevantPeerCode.INCOMPATIBLE_FORKS,
    35→      ours: local.forkDigest,
    36→      theirs: remote.forkDigest,
    37→    };
    38→  }
    39→
    40→  // The remote's head is on a slot that is significantly ahead of what we consider the
    41→  // current slot. This could be because they are using a different genesis time, or that
    42→  // their or our system's clock is incorrect.
    43→  const slotDiff = remote.headSlot - Math.max(currentSlot, 0);
    44→  if (slotDiff > FUTURE_SLOT_TOLERANCE) {
    45→    return {code: IrrelevantPeerCode.DIFFERENT_CLOCKS, slotDiff};
    46→  }
    47→
    48→  // The remote's finalized epoch is less than or equal to ours, but the block root is
    49→  // different to the one in our chain. Therefore, the node is on a different chain and we
    50→  // should not communicate with them.
    51→
    52→  if (
    53→    remote.finalizedEpoch <= local.finalizedEpoch &&
    54→    !isZeroRoot(remote.finalizedRoot) &&
    55→    !isZeroRoot(local.finalizedRoot)
    56→  ) {
    57→    // NOTE: due to preferring to not access chain state here, we can't check the finalized root against our history.
    58→    // The impact of not doing check is low: peers that are behind us we can't confirm they are in the same chain as us.
    59→    // In the worst case they will attempt to sync from us, fail and disconnect. The ENR fork check should be sufficient
    60→    // to differentiate most peers in normal network conditions.
    61→    const remoteRoot = remote.finalizedRoot;
    62→    const expectedRoot = remote.finalizedEpoch === local.finalizedEpoch ? local.finalizedRoot : null;
    63→
    64→    if (expectedRoot !== null && !ssz.Root.equals(remoteRoot, expectedRoot)) {
    65→      return {
    66→        code: IrrelevantPeerCode.DIFFERENT_FINALIZED,
    67→        expectedRoot: expectedRoot, // forkChoice returns Tree BranchNode which the logger prints as {}
    68→        remoteRoot: remoteRoot,
    69→      };
    70→    }
    71→  }
    72→
    73→  if (isForkPostFulu(forkName) && (remote as fulu.Status).earliestAvailableSlot === undefined) {
    74→    return {
    75→      code: IrrelevantPeerCode.NO_EARLIEST_AVAILABLE_SLOT,
    76→    };
    77→  }
    78→
    79→  // Note: Accept request status finalized checkpoint in the future, we do not know if it is a true finalized root
    80→  return null;
    81→}
    82→
    83→export function isZeroRoot(root: Root): boolean {
    84→  const ZERO_ROOT = ssz.Root.defaultValue();
    85→  return ssz.Root.equals(root, ZERO_ROOT);
    86→}
    87→
    88→export function renderIrrelevantPeerType(type: IrrelevantPeerType): string {
    89→  switch (type.code) {
    90→    case IrrelevantPeerCode.INCOMPATIBLE_FORKS:
    91→      return `INCOMPATIBLE_FORKS ours: ${toHex(type.ours)} theirs: ${toHex(type.theirs)}`;
    92→    case IrrelevantPeerCode.DIFFERENT_CLOCKS:
    93→      return `DIFFERENT_CLOCKS slotDiff: ${type.slotDiff}`;
    94→    case IrrelevantPeerCode.DIFFERENT_FINALIZED:
    95→      return `DIFFERENT_FINALIZED root: ${toRootHex(type.remoteRoot)} expected: ${toRootHex(type.expectedRoot)}`;
    96→    case IrrelevantPeerCode.NO_EARLIEST_AVAILABLE_SLOT:
    97→      return "No earliestAvailableSlot announced via peer Status";
    98→  }
    99→}
