    68→ */
    69→export async function recoverDataColumnSidecars(
    70→  partialSidecars: Map<number, fulu.DataColumnSidecar>
    71→): Promise<fulu.DataColumnSidecars | null> {
    72→  const columnCount = partialSidecars.size;
    73→  if (columnCount < NUMBER_OF_COLUMNS / 2) {
    74→    // We don't have enough columns to recover
    75→    return null;
    76→  }
    77→
    78→  if (columnCount === NUMBER_OF_COLUMNS) {
    79→    // full columns, no need to recover
    80→    return Array.from(partialSidecars.values());
