    89→
    90→  const fullColumns: Array<Uint8Array[]> = Array.from(
    91→    {length: NUMBER_OF_COLUMNS},
    92→    () => new Array<Uint8Array>(blobCount)
    93→  );
    94→  const blobProofs: Array<Uint8Array[]> = Array.from({length: blobCount});
    95→  // https://github.com/ethereum/consensus-specs/blob/v1.6.0-alpha.4/specs/fulu/das-core.md#recover_matrix
    96→  const cellsAndProofs = await Promise.all(
    97→    blobProofs.map((_, blobIndex) => {
    98→      const cellIndices: number[] = [];
    99→      const cells: Uint8Array[] = [];
   100→      for (const [columnIndex, dataColumn] of partialSidecars.entries()) {
   101→        cellIndices.push(columnIndex);
   102→        cells.push(dataColumn.column[blobIndex]);
   103→      }
   104→      // recovered cells and proofs are of the same row/blob, their length should be NUMBER_OF_COLUMNS
   105→      return kzg.asyncRecoverCellsAndKzgProofs(cellIndices, cells);
   106→    })
   107→  );
   108→
   109→  for (let blobIndex = 0; blobIndex < blobCount; blobIndex++) {
   110→    const recoveredCells = cellsAndProofs[blobIndex].cells;
   111→    blobProofs[blobIndex] = cellsAndProofs[blobIndex].proofs;
   112→    for (let columnIndex = 0; columnIndex < NUMBER_OF_COLUMNS; columnIndex++) {
   113→      fullColumns[columnIndex][blobIndex] = recoveredCells[columnIndex];
   114→    }
   115→  }
   116→
   117→  const result: fulu.DataColumnSidecars = new Array(NUMBER_OF_COLUMNS);
   118→
   119→  for (let columnIndex = 0; columnIndex < NUMBER_OF_COLUMNS; columnIndex++) {
   120→    let sidecar = partialSidecars.get(columnIndex);
   121→    if (sidecar) {
   122→      // We already have this column
   123→      result[columnIndex] = sidecar;
   124→      continue;
   125→    }
   126→
   127→    sidecar = {
   128→      index: columnIndex,
   129→      column: fullColumns[columnIndex],
   130→      kzgCommitments: firstDataColumn.kzgCommitments,
   131→      kzgProofs: Array.from({length: blobCount}, (_, rowIndex) => blobProofs[rowIndex][columnIndex]),
   132→      signedBlockHeader: firstDataColumn.signedBlockHeader,
   133→      kzgCommitmentsInclusionProof: firstDataColumn.kzgCommitmentsInclusionProof,
   134→    };
   135→    result[columnIndex] = sidecar;
   136→  }
   137→
   138→  return result;
   139→}
