   141→/**
   142→ * Reconstruct blobs from a set of data columns, at least 50%+ of all the columns
   143→ * must be provided to allow to reconstruct the full data matrix
   144→ */
   145→export async function reconstructBlobs(sidecars: fulu.DataColumnSidecars): Promise<deneb.Blobs> {
   146→  if (sidecars.length < NUMBER_OF_COLUMNS / 2) {
   147→    throw Error(
   148→      `Expected at least ${NUMBER_OF_COLUMNS / 2} data columns to reconstruct blobs, received ${sidecars.length}`
   149→    );
   150→  }
   151→
   152→  let fullSidecars: fulu.DataColumnSidecars;
   153→
   154→  if (sidecars.length === NUMBER_OF_COLUMNS) {
   155→    // Full columns, no need to recover
   156→    fullSidecars = sidecars;
   157→  } else {
   158→    const sidecarsByIndex = new Map<number, fulu.DataColumnSidecar>(sidecars.map((sc) => [sc.index, sc]));
   159→    const recoveredSidecars = await recoverDataColumnSidecars(sidecarsByIndex);
   160→    if (recoveredSidecars === null) {
   161→      // Should not happen because we check the column count above
   162→      throw Error("Failed to reconstruct the full data matrix");
   163→    }
   164→    fullSidecars = recoveredSidecars;
   165→  }
   166→
   167→  const blobCount = fullSidecars[0].column.length;
   168→  const blobs: deneb.Blobs = new Array(blobCount);
   169→
   170→  const ordered = fullSidecars.slice().sort((a, b) => a.index - b.index);
   171→  for (let row = 0; row < blobCount; row++) {
   172→    // 128 cells that make up one "extended blob" row
   173→    const cells = ordered.map((col) => col.column[row]);
   174→    blobs[row] = cellsToBlob(cells);
   175→  }
   176→
   177→  return blobs;
   178→}
   179→
   180→/**
   181→ * Concatenate the systematic half (columns 0‑63) of a row of cells into
   182→ * the original 131072 byte blob. The parity half (64‑127) is ignored as
   183→ * it is only needed for erasure‑coding recovery when columns are missing.
   184→ */
   185→function cellsToBlob(cells: fulu.Cell[]): deneb.Blob {
   186→  if (cells.length !== CELLS_PER_EXT_BLOB) {
   187→    throw Error(`Expected ${CELLS_PER_EXT_BLOB} cells to reconstruct blob, received ${cells.length}`);
   188→  }
   189→
   190→  const blob = new Uint8Array(BYTES_PER_FIELD_ELEMENT * FIELD_ELEMENTS_PER_BLOB);
   191→
   192→  // Only the first 64 cells hold the original bytes
   193→  for (let i = 0; i < CELLS_PER_EXT_BLOB / 2; i++) {
   194→    const cell = cells[i];
   195→    if (cell.length !== BYTES_PER_CELL) {
   196→      throw Error(`Cell ${i} has incorrect byte size ${cell.length} != ${BYTES_PER_CELL}`);
   197→    }
   198→
   199→    blob.set(cell, i * BYTES_PER_CELL);
   200→  }
   201→
   202→  return blob;
   203→}
