     8→/**
     9→ * Return the proposer indices for the full available lookahead starting from current epoch.
    10→ * Used to initialize the `proposer_lookahead` field in the beacon state at genesis and after forks.
    11→ */
    12→export function initializeProposerLookahead(state: CachedBeaconStateElectra): ValidatorIndex[] {
    13→  const currentEpoch = state.epochCtx.epoch;
    14→
    15→  const lookahead: ValidatorIndex[] = [];
    16→
    17→  for (let i = 0; i <= MIN_SEED_LOOKAHEAD; i++) {
    18→    const epoch = currentEpoch + i;
    19→
    20→    // Try to pull cached shuffling first
    21→    let shuffling = state.epochCtx.getShufflingAtEpochOrNull(epoch);
    22→
    23→    if (!shuffling) {
    24→      // Only compute epoch shuffling if cache is not yet populated
    25→      let activeIndices: Uint32Array;
    26→      if (epoch === currentEpoch) {
    27→        // This should never happen as current shuffling will always be cached
    28→        activeIndices = state.epochCtx.currentShuffling.activeIndices;
    29→      } else if (epoch === currentEpoch + 1) {
    30→        activeIndices = state.epochCtx.nextActiveIndices;
    31→      } else {
    32→        // This will never be reached with current spec as `MIN_SEED_LOOKAHEAD == 1`
    33→        activeIndices = getActiveValidatorIndices(state, epoch);
    34→      }
    35→
    36→      shuffling = computeEpochShuffling(state, activeIndices, epoch);
    37→    }
    38→
    39→    lookahead.push(...computeProposerIndices(ForkSeq.fulu, state, shuffling, epoch));
    40→  }
    41→
    42→  return lookahead;
    43→}
