   199→  MAX_BLOBS_PER_BLOCK: number;
   200→};
   201→
   202→export type BlobSchedule = BlobScheduleEntry[];
   203→
   204→export function isBlobSchedule(value: unknown): value is BlobSchedule {
   205→  return (
   206→    Array.isArray(value) &&
   207→    value.every(
   208→      (entry) =>
   209→        typeof entry === "object" &&
   210→        entry !== null &&
   211→        typeof entry.EPOCH === "number" &&
   212→        typeof entry.MAX_BLOBS_PER_BLOCK === "number"
   213→    )
   214→  );
   215→}
