   217→/** Allows values in a Spec file */
   218→export type SpecValue = number | bigint | Uint8Array | string | BlobSchedule;
   219→
   220→/** Type value name of each spec field. Numbers are ignored since they are the most common */
   221→export type SpecValueType<V extends SpecValue> = V extends number
   222→  ? "number"
   223→  : V extends bigint
   224→    ? "bigint"
   225→    : V extends Uint8Array
   226→      ? "bytes"
   227→      : V extends string
   228→        ? "string"
   229→        : V extends BlobSchedule
   230→          ? "blob_schedule"
   231→          : never;
