     2→import {deneb, fulu} from "@lodestar/types";
     3→import {kzg} from "../../util/kzg.js";
     4→
     5→/**
     6→ * Optionally sanity-check that the KZG commitments match the versioned hashes in the transactions
     7→ * https://github.com/ethereum/consensus-specs/blob/11a037fd9227e29ee809c9397b09f8cc3383a8c0/specs/eip4844/validator.md#blob-kzg-commitments
     8→ */
     9→export async function validateBlobsAndKzgCommitments(
    10→  commitments: deneb.KZGCommitment[],
    11→  proofs: deneb.KZGProof[],
    12→  blobs: deneb.Blobs
    13→): Promise<void> {
    14→  if (blobs.length !== commitments.length) {
    15→    throw Error(`Blobs bundle blobs len ${blobs.length} != commitments len ${commitments.length}`);
    16→  }
    17→
    18→  if (proofs.length !== blobs.length) {
    19→    throw new Error(`Invalid proofs length for BlobsBundleV1 format: expected ${blobs.length}, got ${proofs.length}`);
    20→  }
    21→
    22→  if (!(await kzg.asyncVerifyBlobKzgProofBatch(blobs, commitments, proofs))) {
    23→    throw new Error("Error in verifyBlobKzgProofBatch");
    24→  }
    25→}
    26→
    27→/**
    28→ * Optionally sanity-check that the KZG commitments match the versioned hashes in the transactions
    29→ */
    30→export async function validateCellsAndKzgCommitments(
    31→  commitments: deneb.KZGCommitment[],
    32→  proofs: fulu.KZGProof[],
    33→  cells: fulu.Cell[][]
    34→): Promise<void> {
    35→  if (cells.length !== commitments.length) {
    36→    throw Error(`Blobs bundle cells len ${cells.length} != commitments len ${commitments.length}`);
    37→  }
    38→
    39→  const expectedProofsLength = cells.length * CELLS_PER_EXT_BLOB;
    40→  if (proofs.length !== expectedProofsLength) {
    41→    throw Error(
    42→      `Invalid proofs length for BlobsBundleV2 format: expected ${expectedProofsLength}, got ${proofs.length}`
    43→    );
    44→  }
    45→
    46→  const commitmentBytes = commitments.flatMap((commitment) => Array(CELLS_PER_EXT_BLOB).fill(commitment));
    47→  const cellIndices = Array.from({length: cells.length}).flatMap(() =>
    48→    Array.from({length: CELLS_PER_EXT_BLOB}, (_, i) => i)
    49→  );
    50→
    51→  if (!(await kzg.asyncVerifyCellKzgProofBatch(commitmentBytes, cellIndices, cells.flat(), proofs.flat()))) {
    52→    throw new Error("Error in verifyCellKzgProofBatch");
    53→  }
    54→}
