    62→function stringifyGossipTopicType(topic: GossipTopic): string {
    63→  switch (topic.type) {
    64→    case GossipType.beacon_block:
    65→    case GossipType.beacon_aggregate_and_proof:
    66→    case GossipType.voluntary_exit:
    67→    case GossipType.proposer_slashing:
    68→    case GossipType.attester_slashing:
    69→    case GossipType.sync_committee_contribution_and_proof:
    70→    case GossipType.light_client_finality_update:
    71→    case GossipType.light_client_optimistic_update:
    72→    case GossipType.bls_to_execution_change:
    73→      return topic.type;
    74→    case GossipType.beacon_attestation:
    75→    case GossipType.sync_committee:
    76→      return `${topic.type}_${topic.subnet}`;
    77→    case GossipType.blob_sidecar:
    78→      return `${topic.type}_${topic.subnet}`;
    79→    case GossipType.data_column_sidecar:
    80→      return `${topic.type}_${topic.subnet}`;
    81→  }
    82→}
