    84→export function getGossipSSZType(topic: GossipTopic) {
    85→  const {fork} = topic.boundary;
    86→  switch (topic.type) {
    87→    case GossipType.beacon_block:
    88→      // beacon_block is updated in altair to support the updated SignedBeaconBlock type
    89→      return ssz[fork].SignedBeaconBlock;
    90→    case GossipType.blob_sidecar:
    91→      return ssz.deneb.BlobSidecar;
    92→    case GossipType.data_column_sidecar:
    93→      return ssz.fulu.DataColumnSidecar;
    94→    case GossipType.beacon_aggregate_and_proof:
    95→      return sszTypesFor(fork).SignedAggregateAndProof;
    96→    case GossipType.beacon_attestation:
    97→      return sszTypesFor(fork).SingleAttestation;
    98→    case GossipType.proposer_slashing:
    99→      return ssz.phase0.ProposerSlashing;
   100→    case GossipType.attester_slashing:
   101→      return sszTypesFor(fork).AttesterSlashing;
   102→    case GossipType.voluntary_exit:
   103→      return ssz.phase0.SignedVoluntaryExit;
   104→    case GossipType.sync_committee_contribution_and_proof:
   105→      return ssz.altair.SignedContributionAndProof;
   106→    case GossipType.sync_committee:
   107→      return ssz.altair.SyncCommitteeMessage;
   108→    case GossipType.light_client_optimistic_update:
   109→      return isForkPostAltair(fork)
   110→        ? sszTypesFor(fork).LightClientOptimisticUpdate
   111→        : ssz.altair.LightClientOptimisticUpdate;
   112→    case GossipType.light_client_finality_update:
   113→      return isForkPostAltair(fork)
   114→        ? sszTypesFor(fork).LightClientFinalityUpdate
   115→        : ssz.altair.LightClientFinalityUpdate;
   116→    case GossipType.bls_to_execution_change:
   117→      return ssz.capella.SignedBLSToExecutionChange;
   118→  }
   119→}
