    case IrrelevantPeerCode.DIFFERENT_FINALIZED:
      return `DIFFERENT_FINALIZED root: ${toRootHex(type.remoteRoot)} expected: ${toRootHex(type.expectedRoot)}`;
    case IrrelevantPeerCode.NO_EARLIEST_AVAILABLE_SLOT:
